WITH car AS (SELECT REPLACE(a.id_imovel,'-','') id_car_norm,a.id_imovel,a.id_municipio,a.area,a.geometria,a.status,a.condicao,a.tipo FROM `basedosdados.br_sfb_sicar.area_imovel` a WHERE a.id_municipio='2929701' AND a.data_extracao>=DATE '2026-06-02' AND a.data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(a.id_imovel,'-','') ORDER BY a.data_extracao DESC)=1),p AS (SELECT DISTINCT ano_emissao,id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm,cpf,cnpj_basico FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao BETWEEN 2013 AND 2026 AND id_car IS NOT NULL AND TRIM(id_car)!=''),d AS (SELECT p.id_car_norm,p.id_imovel,p.area,p.status,p.condicao,p.tipo,p.ano_emissao,p.id_referencia_bacen,p.numero_ordem,COALESCE(NULLIF(p.cpf,''),NULLIF(p.cnpj_basico,'')) documento FROM p JOIN car USING(id_car_norm) WHERE car.area<0.1 AND COALESCE(NULLIF(p.cpf,''),NULLIF(p.cnpj_basico,'')) IS NOT NULL) SELECT id_imovel,area,status,condicao,tipo,COUNT(DISTINCT documento) mutuarios,COUNT(DISTINCT id_referencia_bacen) operacoes,COUNT(DISTINCT ano_emissao) anos,MIN(ano_emissao) primeiro_ano,MAX(ano_emissao) ultimo_ano FROM d GROUP BY 1,2,3,4,5 ORDER BY mutuarios DESC,operacoes DESC LIMIT 10